import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const m=JSON.parse('{"title":"Paste from other apps","description":"Paste text, tables, and images into a doc from web pages, spreadsheets, Markdown, and other documents, with or without formatting.","frontmatter":{"title":"Paste from other apps","description":"Paste text, tables, and images into a doc from web pages, spreadsheets, Markdown, and other documents, with or without formatting.","type":"how-to"},"headers":[],"relativePath":"docs-editor/paste-from-other-apps.md","filePath":"docs-editor/paste-from-other-apps.md"}'),r={name:"docs-editor/paste-from-other-apps.md"};function i(d,e,l,n,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="paste-from-other-apps" tabindex="-1">Paste from other apps <a class="header-anchor" href="#paste-from-other-apps" aria-label="Permalink to &quot;Paste from other apps&quot;">​</a></h1><p>Paste content into a doc and keep as much of its structure as the doc can hold. Press <code>⌘+V</code> / <code>Ctrl+V</code>, or right-click and select <strong>Paste</strong>.</p><p>Right-click <strong>Paste</strong> may ask for clipboard permission the first time, and it pastes text and formatted text only. To paste an image or content copied from a Wafflebase doc, press <code>⌘+V</code> / <code>Ctrl+V</code>.</p><h2 id="what-a-paste-keeps" tabindex="-1">What a paste keeps <a class="header-anchor" href="#what-a-paste-keeps" aria-label="Permalink to &quot;What a paste keeps&quot;">​</a></h2><p>The doc checks the clipboard in this order and uses the first match:</p><table tabindex="0"><thead><tr><th>On the clipboard</th><th>What you get</th></tr></thead><tbody><tr><td>An image, such as a screenshot or a copied picture</td><td>The image, inserted at the cursor</td></tr><tr><td>Content copied from a Wafflebase doc</td><td>The same content with all of its formatting</td></tr><tr><td>Formatted text from a web page or word processor</td><td>Headings, bulleted and numbered lists, links, tables, bold, italic, underline, strikethrough, text and highlight colors, and font sizes</td></tr><tr><td>A Markdown table (rows like <code>| a | b |</code> under a <code>| --- |</code> separator)</td><td>A real table</td></tr><tr><td>Any other text</td><td>One paragraph per line</td></tr></tbody></table><p>From formatted text, a paste drops images, font families, and how deep list items were nested.</p><h2 id="paste-formatted-text" tabindex="-1">Paste formatted text <a class="header-anchor" href="#paste-formatted-text" aria-label="Permalink to &quot;Paste formatted text&quot;">​</a></h2><ol><li>Copy the text in the other app.</li><li>Click where it should go in the doc and press <code>⌘+V</code> / <code>Ctrl+V</code>.</li></ol><p>The text keeps its headings, lists, links, and character styles. Reapply fonts with <a href="/docs/docs-editor/format-text.html">Format text</a> if needed.</p><h2 id="paste-as-plain-text" tabindex="-1">Paste as plain text <a class="header-anchor" href="#paste-as-plain-text" aria-label="Permalink to &quot;Paste as plain text&quot;">​</a></h2><ol><li>Copy the text.</li><li>Press <code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code>.</li></ol><p>All formatting is dropped, and each line becomes a paragraph. The text takes the style of the paragraph you paste into.</p><h2 id="paste-a-spreadsheet-range-or-table" tabindex="-1">Paste a spreadsheet range or table <a class="header-anchor" href="#paste-a-spreadsheet-range-or-table" aria-label="Permalink to &quot;Paste a spreadsheet range or table&quot;">​</a></h2><ol><li>Copy the cells in a spreadsheet, such as a Wafflebase sheet, or copy a table from a web page.</li><li>Click where the table should go and press <code>⌘+V</code> / <code>Ctrl+V</code>.</li></ol><p>A new table appears with the copied rows and columns.</p><h3 id="paste-into-an-existing-table" tabindex="-1">Paste into an existing table <a class="header-anchor" href="#paste-into-an-existing-table" aria-label="Permalink to &quot;Paste into an existing table&quot;">​</a></h3><p>What happens depends on what you copied:</p><ul><li><strong>Cells</strong> (a spreadsheet range, a web table, a Markdown table, or cells selected inside a Wafflebase table) fill the table starting at the cell with the cursor. Cells that would fall outside the table are left out.</li><li><strong>A whole table</strong> copied from a Wafflebase doc is placed inside the current cell as a nested table.</li></ul><p>To keep the existing table&#39;s size, copy only as many cells as there is room for.</p><h2 id="paste-markdown" tabindex="-1">Paste Markdown <a class="header-anchor" href="#paste-markdown" aria-label="Permalink to &quot;Paste Markdown&quot;">​</a></h2><p>A Markdown table becomes a real table. Other Markdown lines, such as <code># Heading</code> or <code>- item</code>, are pasted as plain text with their symbols. To format them, type the shortcuts instead; see <a href="/docs/docs-editor/format-text.html">Format text</a> and <a href="/docs/docs-editor/lists-and-indents.html">Lists and indents</a>.</p><h2 id="paste-an-image" tabindex="-1">Paste an image <a class="header-anchor" href="#paste-an-image" aria-label="Permalink to &quot;Paste an image&quot;">​</a></h2><ol><li>Copy an image, or take a screenshot to the clipboard.</li><li>Click in the doc and press <code>⌘+V</code> / <code>Ctrl+V</code>.</li></ol><p>If the clipboard holds both an image and text, the image wins. See <a href="/docs/docs-editor/images.html">Images</a> for sizes and file types.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Tables can&#39;t be pasted into a header or footer. Text pastes there as usual.</li><li>A very large paste shows <strong>Pasting a large document…</strong> while it runs. Wait for it to finish before typing.</li><li>A paste is a single step: press <code>⌘+Z</code> / <code>Ctrl+Z</code> once to undo all of it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/tables.html">Tables</a> to adjust a pasted table.</li><li><a href="/docs/files/import-export.html">Import and export</a> to open a whole Word file instead of pasting it.</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a> for clipboard shortcuts.</li></ul>',29)])])}const f=t(r,[["render",i]]);export{m as __pageData,f as default};
